SvxPresetListBox::SvxPresetListBox(std::unique_ptr<weld::ScrolledWindow> pWindow)
    : ValueSet(std::move(pWindow))
    , aIconSize(60, 64)
    , mnContextMenuItemId(0)
{
    SetEdgeBlending(true);
}
